import {Game,SKILLS,clamp} from './core.js';
import {MILESTONES} from './roadmap.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const game=new Game();const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const settings={intensity:1,shake:!reduced,quality:'medium'};let canvas=$('#world'),view,pausedByUser=false,page='lab',last=performance.now(),auto=false,autoTimer=0,autoStep=0,soundOn=false,audioCtx=null,toastTimer=0;
$('#camera-shake').checked=settings.shake;
const toast=(message)=>{const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2200);};
function log(message){const li=document.createElement('li');li.textContent=message;$('#event-log').prepend(li);while($('#event-log').children.length>3)$('#event-log').lastElementChild.remove();}
function select(id){const s=SKILLS[id];$$('.skill-card').forEach(b=>{b.classList.toggle('selected',b.dataset.skill===id);b.setAttribute('aria-pressed',String(b.dataset.skill===id));});$('#skill-category').textContent=s.system;$('#skill-category').style.color=s.color;$('#skill-category').style.borderColor=s.color+'44';$('#detail-glyph').textContent=s.symbol;$('#detail-glyph').className='detail-glyph '+s.theme;$('#detail-english').textContent=s.english;$('#detail-name').textContent=s.name;$('#detail-description').textContent=s.description;$('#detail-damage').textContent=s.damage;$('#detail-cooldown').innerHTML=s.cooldown+' <em>giây</em>';$('#detail-cast').innerHTML=s.charge+' <em>giây</em>';$('#detail-cost').innerHTML=s.cost+' <em>◈</em>';$('#cast-button').className='cast-button '+s.theme;$('#cast-button span').textContent='Thi triển '+s.name;$('#cast-button kbd').textContent=s.key;}
game.on('select',select);game.on('notice',toast);game.on('charge',e=>{log('Đang niệm '+SKILLS[e.id].name.toLowerCase()+'…');tone(e.id,'charge');});game.on('release',e=>{log('Đã thi triển '+SKILLS[e.id].name.toLowerCase()+'.');tone(e.id,'release');});game.on('hit',e=>{log('Mục tiêu '+(e.id+1)+' nhận '+e.damage+' sát thương.');tone(e.kind,'hit');});game.on('defeat',()=>toast('Hạ mục tiêu! Hồi sinh sau 3,5 giây.'));game.on('reset',()=>{select('bolt');$('#event-log').replaceChildren();log('Buổi tập mới. Chọn vị trí và thử skill.');});
function tone(id,phase){if(!soundOn||!audioCtx)return;const now=audioCtx.currentTime,osc=audioCtx.createOscillator(),gain=audioCtx.createGain(),base={bolt:190,beam:430,nova:110}[id];osc.type=phase==='hit'?'triangle':'sine';osc.frequency.setValueAtTime(phase==='release'?base*2:base,now);osc.frequency.exponentialRampToValueAtTime(phase==='charge'?base*2:Math.max(30,base*.4),now+.25);gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(.035,now+.025);gain.gain.exponentialRampToValueAtTime(.0001,now+.28);osc.connect(gain);gain.connect(audioCtx.destination);osc.start(now);osc.stop(now+.3);osc.onended=()=>{osc.disconnect();gain.disconnect();};}
$('#sound-button').addEventListener('click',async()=>{try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();await audioCtx.resume();soundOn=!soundOn;$('#sound-button').setAttribute('aria-pressed',String(soundOn));$('#sound-button').setAttribute('aria-label',soundOn?'Tắt âm thanh':'Bật âm thanh');$('#sound-button').title=soundOn?'Tắt âm thanh':'Bật âm thanh';toast(soundOn?'Đã bật âm thanh':'Đã tắt âm thanh');}catch{toast('Trình duyệt chưa hỗ trợ âm thanh.');}});
function stopAuto(){auto=false;$('#showcase-button').innerHTML='<span class="play-icon">▷</span> Xem chuỗi skill';$('#showcase-button').setAttribute('aria-pressed','false');}
$$('.skill-card').forEach(b=>b.addEventListener('click',()=>{stopAuto();game.cast(b.dataset.skill);}));$('#cast-button').addEventListener('click',()=>{stopAuto();game.cast();});
$('#showcase-button').addEventListener('click',()=>{if(auto){stopAuto();return;}if(pausedByUser){pausedByUser=false;applyPause();}auto=true;autoTimer=.2;autoStep=0;$('#showcase-button').innerHTML='<span class="play-icon">Ⅱ</span> Dừng trình diễn';$('#showcase-button').setAttribute('aria-pressed','true');toast('Đang trình diễn — di chuyển hoặc dùng skill để dừng.');});
$('#reset-button').addEventListener('click',()=>{stopAuto();pausedByUser=false;game.reset();applyPause();toast('Đã hồi đầy năng lượng và đặt lại mục tiêu.');});
function applyPause(){game.paused=pausedByUser||page!=='lab'||document.hidden;$('#pause-overlay').hidden=!pausedByUser;$('#pause-button').setAttribute('aria-pressed',String(pausedByUser));$('#pause-button').setAttribute('aria-label',pausedByUser?'Tiếp tục sân tập':'Tạm dừng sân tập');$('#pause-button').textContent=pausedByUser?'▷':'Ⅱ';}
$('#pause-button').addEventListener('click',()=>{pausedByUser=!pausedByUser;applyPause();});$('#resume-button').addEventListener('click',()=>{pausedByUser=false;applyPause();});document.addEventListener('visibilitychange',()=>{keys.clear();touchMove={x:0,z:0};applyPause();});
$('#fx-intensity').addEventListener('input',e=>{settings.intensity=Number(e.target.value)/100;$('#fx-value').textContent=e.target.value+'%';});$('#quality').addEventListener('change',e=>{settings.quality=e.target.value;view?.resize();toast('Đã chuyển chất lượng: '+e.target.selectedOptions[0].textContent);});$('#camera-shake').addEventListener('change',e=>settings.shake=e.target.checked);
const keys=new Set();let touchMove={x:0,z:0};
window.addEventListener('keydown',e=>{if(page!=='lab'||e.ctrlKey||e.altKey||e.metaKey||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright',' '].includes(k))e.preventDefault();if(['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright'].includes(k)){stopAuto();keys.add(k);}if(e.repeat)return;const id={q:'bolt',e:'beam',r:'nova'}[k];if(id){stopAuto();game.cast(id);}if(k===' '&&!/BUTTON/.test(e.target.tagName)){stopAuto();game.cast();}if(k==='escape'){pausedByUser=!pausedByUser;applyPause();}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();touchMove={x:0,z:0};});
const joystick=$('#joystick');let joyPointer=null;
function updateJoy(e){const r=joystick.getBoundingClientRect(),x=clamp((e.clientX-r.left-r.width/2)/25,-1,1),y=clamp((e.clientY-r.top-r.height/2)/25,-1,1);joystick.querySelector('i').style.transform=`translate(${x*17}px,${y*17}px)`;touchMove={x:(x+y)*.707,z:(y-x)*.707};}
joystick.addEventListener('pointerdown',e=>{stopAuto();joyPointer=e.pointerId;joystick.setPointerCapture(e.pointerId);updateJoy(e);});joystick.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)updateJoy(e);});const endJoy=()=>{joyPointer=null;touchMove={x:0,z:0};joystick.querySelector('i').style.transform='';};joystick.addEventListener('pointerup',endJoy);joystick.addEventListener('pointercancel',endJoy);joystick.addEventListener('lostpointercapture',endJoy);
let completed=[];try{completed=JSON.parse(localStorage.getItem('aether-roadmap-v1')||'[]');if(!Array.isArray(completed))completed=[];}catch{}
$('#milestones').innerHTML=MILESTONES.map((m,i)=>`<article class="milestone ${completed.includes(i)?'complete':''}"><div class="milestone-top"><span class="milestone-number">${String(i+1).padStart(2,'0')}</span><span class="milestone-stage">${m.stage.split(' / ')[1]}</span></div><h2>${m.title}</h2><p>${m.description}</p><ul>${m.tasks.map(s=>'<li>'+s+'</li>').join('')}</ul><div class="done-criterion"><strong>Đủ điều kiện đi tiếp:</strong> ${m.done}</div><label><input type="checkbox" data-milestone="${i}" ${completed.includes(i)?'checked':''}> Tôi đã hoàn thành cột mốc này</label></article>`).join('');
function roadmapProgress(){const n=completed.length;$('#roadmap-count').textContent=n+' / 7 cột mốc';$('#roadmap-fill').style.width=n/7*100+'%';}
$$('[data-milestone]').forEach(input=>input.addEventListener('change',()=>{completed=$$('[data-milestone]').filter(n=>n.checked).map(n=>Number(n.dataset.milestone));input.closest('article').classList.toggle('complete',input.checked);try{localStorage.setItem('aether-roadmap-v1',JSON.stringify(completed));}catch{}roadmapProgress();}));roadmapProgress();
function changePage(next){page=next;$('#lab-page').hidden=page!=='lab';$('#roadmap-page').hidden=page!=='roadmap';$$('.nav-button').forEach(b=>{const active=b.dataset.page===page;b.classList.toggle('active',active);active?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current');});if(page==='roadmap')stopAuto();keys.clear();applyPause();if(page==='lab')view?.resize();}
$$('[data-page]').forEach(b=>b.addEventListener('click',()=>{location.hash=b.dataset.page;}));window.addEventListener('hashchange',()=>changePage(location.hash==='#roadmap'?'roadmap':'lab'));$('.brand').addEventListener('click',()=>changePage('lab'));changePage(location.hash==='#roadmap'?'roadmap':'lab');
function attachCanvas(){canvas.addEventListener('pointermove',e=>{if(!game.paused)view?.aim(e.clientX,e.clientY);});canvas.addEventListener('pointerdown',e=>{if(!game.paused){view?.aim(e.clientX,e.clientY);canvas.focus({preventScroll:true});}});canvas.addEventListener('contextmenu',e=>e.preventDefault());}
async function compatibility(){// Failed WebGL canvases cannot always be reused as 2D contexts.
  const next=canvas.cloneNode(false);canvas.replaceWith(next);canvas=next;const {CompatibilityView}=await import('./fallback.js');view=new CompatibilityView(canvas,game,settings);$('#renderer-badge').textContent='CHẾ ĐỘ TƯƠNG THÍCH';$('#renderer-badge').title='Trình duyệt không có WebGL. Hiệu ứng được đơn giản hóa; điều khiển và sát thương giữ nguyên.';$('#render-mode').textContent='HIỆU ỨNG ĐƠN GIẢN';attachCanvas();
}
try{const {View3D}=await import('./view3d.js');view=new View3D(canvas,game,settings);$('#renderer-badge').textContent='3D · THREE.JS';attachCanvas();canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();pausedByUser=true;applyPause();toast('Đồ họa bị gián đoạn. Tải lại trang để tiếp tục.');});}catch(error){console.warn('Using compatibility view:',error.message);try{await compatibility();}catch{const box=$('#loading');box.replaceChildren();const msg=document.createElement('p');msg.textContent='Trình duyệt chưa hỗ trợ vẽ sân tập. Bạn vẫn có thể xem tab Lộ trình.';box.append(msg);throw error;}}
$('#loading').hidden=true;new ResizeObserver(()=>{if(page==='lab')view.resize();}).observe($('#stage'));select('bolt');
let fpsTime=0,frames=0,uiTime=0;
function frame(now){const dt=Math.min(.05,Math.max(0,(now-last)/1000));last=now;requestAnimationFrame(frame);if(page!=='lab'||document.hidden)return;
  if(!game.paused){let x=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),y=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);game.input={x:(x+y)*.707+touchMove.x,z:(y-x)*.707+touchMove.z};if(auto){autoTimer-=dt;if(autoTimer<=0&&!game.player.cast){const id=['bolt','beam','nova'][autoStep%3],target=game.targets.find(t=>t.hp>0)||game.targets[0];game.setAim(target.x,target.z);if(game.cast(id)){autoStep++;autoTimer=2.3;}else autoTimer=.5;}}game.update(dt);}
  const labels=view.render(dt);const layer=$('#damage-layer');while(layer.children.length<labels.length){const el=document.createElement('span');el.className='damage-number';layer.append(el);}while(layer.children.length>labels.length)layer.lastElementChild.remove();labels.forEach((n,i)=>{const el=layer.children[i];el.textContent=n.text;el.style.left=n.x+'px';el.style.top=n.y+'px';el.style.color=n.color;el.style.opacity=n.visible?n.alpha:0;});
  frames++;fpsTime+=dt;uiTime+=dt;if(fpsTime>=.5){$('#fps').textContent=Math.round(frames/fpsTime);frames=0;fpsTime=0;}if(uiTime>.06){uiTime=0;$('#total-damage').textContent=game.stats.damage.toLocaleString('vi-VN');$('#kills').innerHTML=game.stats.kills+' <em>/ ∞</em>';$('#mana-value').textContent=Math.floor(game.player.mana);$('#mana-fill').style.width=game.player.mana+'%';const cast=game.player.cast;$('#cast-indicator').hidden=!cast;if(cast){$('#cast-text').textContent='Đang niệm '+SKILLS[cast.id].name.toLowerCase();$('#cast-progress').style.width=cast.elapsed/cast.duration*100+'%';}$$('.skill-card').forEach(b=>{const id=b.dataset.skill,left=game.cooldowns[id];b.querySelector('.cooldown-mask').style.transform=`scaleY(${left/SKILLS[id].cooldown})`;b.querySelector('.cooldown-number').textContent=left>.05?left.toFixed(1):'';b.setAttribute('aria-label',`${SKILLS[id].name}, phím ${SKILLS[id].key}${left>.05?', còn '+left.toFixed(1)+' giây hồi chiêu':''}`);});}
}
requestAnimationFrame(frame);
